function buildWord(details: Details, category: Category, partOfSpeech: string, forms: EverydayWord['forms']): EverydayWord {
  const [term, ipa, thaiReading, meaning, context, when, situations, collocations, patterns, examples, similar, mistake, first, second] = details
  const id = `everyday-word-${term.replaceAll(' ', '-')}`
  const [wrong, right, note] = mistake
  return {
    id, term, ipa, thaiReading, partOfSpeech, forms, level: levels[term] ?? 'starter',
    categories: [category, ...(linkedCategories[term] ?? [])],
    senses: [{
      id: 'everyday-use', meaning, context, when, situations, register: 'neutral',
      collocations, patterns, examples: examples.map(([en, th, note]) => ({ en, th, note })),
      similar: similar.map(([term, note]) => ({ term, note })), mistakes: [{ wrong, right, note }],
    }, ...(extraSenses[term] ?? [])],
    exercises: [first, second].map(([prompt, answers, explanation], index) => {
      const order = prompt.startsWith('เรียง')
      const options = order ? prompt.slice(prompt.lastIndexOf(':') + 1).trim().split(' / ') : undefined
      return {
        id: `${id}-e${index + 1}`, kind: order ? 'order' : 'fill', prompt,
        answers: typeof answers === 'string' ? [answers] : answers,
        hint: patterns[0], explanation, difficulty: index === 0 ? 'recognition' : 'guided',
        ...(options && typeof answers === 'string' && options.flatMap((option) => option.split(' ')).length === answers.split(' ').length ? { options } : {}),
      }
    }),
  }
}

function verbs(rows: Verb[], category: Category): EverydayWord[] {
  return rows.map(([[v2, v3, ing, thirdPerson], ...details]) => {
    const [term] = details
    return buildWord(details, category, term.includes(' ') ? 'Verb phrase' : 'Verb', [
      { label: 'V1', word: term }, { label: 'V2', word: v2 }, { label: 'V3', word: v3 },
      { label: 'V-ing', word: ing }, { label: 'He / She / It', word: thirdPerson },
    ])
  })
}

export const words: EverydayWord[] = [
  ...verbs(daily, 'daily-actions'),
  ...verbs(movements, 'physical-movements'),
  ...emotions.map(([family, ...details]) => buildWord(details, 'emotions', 'Adjective', family.map(([label, word]) => ({ label, word })))),
  ...verbs(clothing, 'clothing'),
  ...verbs(household, 'household'),
  ...verbs(cooking, 'cooking'),
  ...verbs(social, 'social'),
  ...verbs(sounds, 'sounds'),
]
